import sys
import requests
import logging
import re
from urllib.parse import urlparse
from typing import Optional

# Configure logging to probe.log with minimal sensitive data
logging.basicConfig(
    filename='probe.log',
    filemode='a',
    level=logging.INFO,
    format='%(message)s'
)

# Define allowed schemes and patterns
ALLOWED_SCHEMES = {'http', 'https'}
MALICIOUS_PATTERNS = [
    r'javascript:', r'data:', r'file://', r'//', r';', r'&', r'|', r'..', r'../',
    r'rm', r'exec', r'bash', r'curl', r'wget', r'python', r'os.system'
]

def is_valid_url(url: str) -> bool:
    """Validate URL format and scheme"""
    if not url or not isinstance(url, str):
        return False

    try:
        parsed = urlparse(url)
        if not parsed.scheme or parsed.scheme not in ALLOWED_SCHEMES:
            return False

        # Check for malicious patterns in the URL
        for pattern in MALICIOUS_PATTERNS:
            if re.search(pattern, url, re.IGNORECASE):
                return False

        # Prevent path traversal attempts
        if '..' in parsed.path or '/.' in parsed.path:
            return False

        return True
    except Exception:
        return False

def sanitize_url(url: str) -> str:
    """Sanitize URL by removing malicious patterns and ensuring safe format"""
    if not url or not isinstance(url, str):
        return ""

    # Remove any potentially dangerous characters or patterns
    url = re.sub(r'javascript:|data:|file://|//', '', url, flags=re.IGNORECASE)
    url = re.sub(r';|&|\||\s+', ' ', url)
    url = url.strip()

    # Ensure it starts with a valid scheme
    if not url.startswith('http'):
        url = 'http://' + url

    return url

def get_safe_status_code(url: str) -> str:
    """Safely get status code or error message with input validation"""
    if not is_valid_url(url):
        return "Invalid URL: scheme or content not allowed"

    sanitized_url = sanitize_url(url)

    try:
        response = requests.get(sanitized_url, timeout=5)
        return str(response.status_code)
    except requests.exceptions.RequestException as e:
        # Log the exception without exposing full traceback
        return f"Request failed: {str(e)}"

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split(' ', 1)
        if len(parts) != 2:
            continue

        label, url = parts[0], parts[1]

        # Validate and sanitize the URL before processing
        output_value = get_safe_status_code(url)

        # Print to stdout with sanitized output
        print(f"{label} {output_value}")

        # Log only the sanitized output to avoid sensitive data exposure
        logging.info(f"{label} {output_value}")

if __name__ == "__main__":
    main()
